scripts.何梅对话.txt:
// 与何梅（同伴）的对话

	Say("何梅（害羞的）：独孤公子，我们……我们走吧。", 66);
	Say("独孤剑：好的。", 1);
	Return;

scripts.小雷对话.txt:
// 与小雷的同伴对话

	If ($Event == 270) @Event270;
	Return;

@Event270:
	Say("小雷：张姐姐和段芙蓉姑娘都是有名的美人，小雷在一日之内居然见到了临安四大美人中的两位，真是艳服不浅哪，哈哈！", 69);
	Return;

scripts.渔夫对话.txt:
//和渔夫的对话

	If($Event == 80) @Event80;
	If($Event == 180) @Event180;

	Say("渔夫：年成这么差，官府又要加渔税，唉，眼见日子一天难似一天。", 0);
	Return;

@Event80:
	If($TalkYufu == 0) @TalkYufu0;
	If($TalkYufu == 1) @TalkYufu1;
 @TalkYufu0:
	Say("渔夫：刚才有两个灰衣人带着一个绿衣少女，驾船去碧霞岛了。", 0);	
	Say("独孤剑：老伯，能否租条船上碧霞岛一趟？", 1);
	Say("渔夫：这么大的雾，很难啊。只有老王才有这本事。", 0);
	Say("独孤剑：老王是谁？", 1);
	Say("渔夫：前面房子里的老汉，刚出海回来。不过他的怪脾气谁都知道，一天只出海一次。", 0);
	Memo("得知采花贼去往碧霞岛，须找一个叫老王的渔夫才能前往。");
	Assign($TalkYufu, 1);
	SetMapTrap(01,"trap01.txt");
	SetMapTrap(02,"trap02.txt");
	SetMapTrap(03,"trap03.txt");	
	Return;
 @TalkYufu1:
	Say("渔夫：去找找老王吧。", 0);
	SetMapTrap(01,"trap01.txt");
	SetMapTrap(02,"trap02.txt");
	SetMapTrap(03,"trap03.txt");	
	Return;

@Event180:
	Say("渔民：是你救出了这些女孩？真是英雄出少年啊.", 0);
	Return;

scripts.渔妇1对话.txt:
// 与海边小渔村渔妇1的对话

	Say("渔妇：我们这个小渔村全靠捕鱼为生，本来就很穷，官府还三天两头征收苛捐杂税，这日子简直没法过了！", 0);
	Return;

scripts.渔妇2对话.txt:
// 与海边小渔村渔妇2的对话

	Say("渔妇：年年补网年年破，日日打鱼日日饥。", 0);
	Return;

